javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const item = event.payload && event.payload.cellContext && event.payload.cellContext.cell && event.payload.cellContext.cell.metadata && event.payload.cellContext.cell.metadata.item;

    if (item && item.isFavorite) {
        return {
            favorite: item,
            actionType: "delete"
        };
    } else {
        return {
            favorite: item,
            actionType: "upsert"
        };
    }
})

